insert into public.properties (id, tenant_id, slug, name, status, booking_mode, pricing_model, summary, description, house_rules, included, tagline, testimonials, street, city, postal_code, country, latitude, longitude, max_guests, bedrooms, bathrooms, check_in_from, check_out_until, cleaning_gap_days, pets_allowed, tourist_tax_included, tourist_tax_cents, accommodation_vat_bp, contact_email, contact_phone, sort) values ('b0000000-0000-4000-8000-000000000100', 'a0000000-0000-4000-8000-000000000002', 'chalet-stromy', 'Chalet STRÖMY', 'published', 'whole', 'per_night', '{"sk": "Moderný chalet pre 8–12 hostí v Demänovskej doline, so saunou a vonkajšou vírivkou, pár minút od Jasnej."}'::jsonb, '{"sk": "Chalet STRÖMY stojí v komplexe Tri Vody v Demänovskej doline. Prenajíma sa celý — 4 spálne s 8 pevnými lôžkami, prístelky, futónové postele a detská postieľka pre spolu 8 až 12 osôb, 3 kúpeľne, 2 obývačky, 2 kuchyne a 2 terasy.\n\nPo lyžovačke na Jasnej (skibus zastavuje pod komplexom) čaká fínska sauna a vonkajšia vírivka s výhľadom do doliny. V lete sú na dosah Demänovské jaskyne, Tatralandia, Bešeňová aj Liptovská Mara."}'::jsonb, '{"sk": "Príchod od 15:00, odchod do 10:00 (bezkontaktný check-in). Nočný kľud 22:00–6:00. V interiéri je zakázané fajčiť a používať otvorený oheň. Zvieratá po dohode za poplatok."}'::jsonb, '{"sk": "Posteľná bielizeň, uteráky, župany, plachty do sauny, wellness, energie, Wi-Fi, parkovanie a online check-in. Žiadne skryté poplatky."}'::jsonb, '{"sk": "Celý len pre vás."}'::jsonb, '[{"author": "Elizabeth Kohutova", "text": "Toto miesto… nádherné! Skvelá lokalita a služby na vysokej úrovni. Strávili sme tu pár dní s rodinou a som veľmi nadšená! Určite sa vrátime."}, {"author": "Patricia Vittek", "text": "Neviem si predstaviť lepšie miesto na oddych a vypnutie hlavy. Atmosféra hôr je jednoducho TOP!"}, {"author": "Eva Milistenferova", "text": "S priateľmi sme si užili skvelé ubytovanie s kompletným vybavením. Určite sa sem radi vrátime."}]'::jsonb, 'Do doliny 1, komplex Tri Vody', 'Demänovská dolina', '031 01', 'SK', 48.996, 19.583, 12, 4, 3, '15:00', '10:00', 0, true, true, 0, 0, 'kontakt@chaletstromy.sk', '+421 905 109 393', 0) on conflict (id) do nothing;
insert into public.property_private (property_id, tenant_id, arrival_instructions) values ('b0000000-0000-4000-8000-000000000100', 'a0000000-0000-4000-8000-000000000002', '{"sk": "Ukážkové pokyny: príchod od 15:00, parkovanie na 2 vyhradených miestach pred chaletom. Prístupové kódy pošle majiteľka v e-maile pred príchodom."}'::jsonb) on conflict (property_id) do nothing;
